using System;
using System.Collections.Generic;
using System.ComponentModel;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Windows.Forms;

internal static class CopyEditingTests
{
    static readonly BindingFlags flags=BindingFlags.Instance|BindingFlags.NonPublic;
    static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
    static void Near(double a,double b,string message){Check(Math.Abs(a-b)<.0001,message+": "+a+"/"+b);}
    static object Get(object o,string name){return o.GetType().GetField(name,flags).GetValue(o);}
    static void Set(object o,string name,object value){o.GetType().GetField(name,flags).SetValue(o,value);}
    static object Call(object o,string name,params object[] args){return o.GetType().GetMethods(flags).Single(m=>m.Name==name&&m.GetParameters().Length==args.Length).Invoke(o,args);}
    static void InspectorImage(ParameterInspector inspector,string file){var parent=inspector.Parent;var table=parent as TableLayoutPanel;var cell=table==null?new TableLayoutPanelCellPosition(0,0):table.GetCellPosition(inspector);parent.Controls.Remove(inspector);using(var host=new Panel{Size=new Size(360,760),BackColor=Theme.Panel}){inspector.Dock=DockStyle.Fill;host.Controls.Add(inspector);host.CreateControl();host.PerformLayout();using(var image=new Bitmap(host.Width,host.Height)){host.DrawToBitmap(image,host.ClientRectangle);image.Save(file);}host.Controls.Remove(inspector);}if(table!=null)table.Controls.Add(inspector,cell.Column,cell.Row);else parent.Controls.Add(inspector);}
    static Track Rod(string id){return new Track{id=id,name=id,kind="rod",shape="polygon",count=5,radius=20,angle=30,x=200,y=160,start=0,end=80,sprite="sprCherry",color="#FFFFFF",lane=0};}
    static EditorState Scene(params Track[] tracks){var s=new EditorState{fps=50,duration=400,randomSeed=991,tracks=tracks.ToList()};Motion.Normalize(s);return s;}
    static object Rows(BulletWorld w){return w.bullets.Where(b=>!b.dead&&b.birth<=w.Frame).Select(b=>new{source=b.source.id,b.birth,b.index,b.generation,b.x,b.y,b.speed,b.direction,b.kinematic,b.clockShift,color=b.color.R+b.color.G*256+b.color.B*65536,image=b.frozenImage>=0?b.frozenImage:Rainbow.Index(b.source,b.sequence,w.Frame-b.clockShift,(b.kinematic?w.Frame:b.birth)-b.clockShift)}).ToArray();}
    static object Sample(EditorState state,int frame){var w=new BulletWorld(state);w.Seek(frame);return new{bullets=Rows(w),values=w.State.tracks.Where(t=>t.kind=="effect").ToDictionary(t=>t.id,t=>Motion.Value(t,"fxOpacity",frame))};}
    static EditorState Fixture(){
        var source=Rod("circle-source");source.rainbow=true;source.sprite=Rainbow.Sprite;Motion.SetKey(source,"angle",0,30);Motion.SetKey(source,"angle",80,90);var s=Scene(source);
        var circle=GenerationPresets.Apply(s,source,CopyGeneration.Key);circle.copyMode="circle";circle.copyCount=8;circle.copyRadius=100;circle.copyFacing="inward";circle.copyColorMode="rainbow";circle.start=5;circle.spawnRepeat=25;
        var gridSource=Rod("grid-source");gridSource.lane=1;gridSource.shape="star2";gridSource.x=550;gridSource.y=240;gridSource.radius=14;s.tracks.Add(gridSource);var grid=GenerationPresets.Apply(s,gridSource,CopyGeneration.Key);grid.copyMode="grid";grid.copyWidth=160;grid.copyHeight=80;grid.copySpacingX=80;grid.copySpacingY=80;grid.copyAngle=30;grid.copyFacing="fixed";grid.copyFacingAngle=15;grid.copyColorMode="fixed";grid.copyColor="#6DE8FF";grid.start=2;grid.spawnRepeat=35;
        var obj=new Track{id="object-source",name="object-source",kind="object",start=10,end=25,x=650,y=100,angle=45,sprite="sprCherry",lane=2};s.tracks.Add(obj);var directions=GenerationPresets.Apply(s,obj,CopyGeneration.Key);directions.copyCount=2;directions.copySpacingX=40;directions.spawnRepeat=0;
        var group=new Track{id="group-source",name="group-source",kind="group",start=0,end=60,x=400,y=400,lane=3};var child=new Track{id="group-child",name="group-child",kind="emitter",parentId=group.id,start=0,end=60,count=1,interval=10,life=40,speed=2,angle=45,x=20,y=0,sprite="sprCherry",lane=3,randomPerInstance=true};child.expressions["angle"]="random_range(-30,30)";s.tracks.Add(group);s.tracks.Add(child);var groupCopy=GenerationPresets.Apply(s,group,CopyGeneration.Key);groupCopy.copyMode="circle";groupCopy.copyCount=3;groupCopy.copyRadius=80;groupCopy.copyFacing="tangent";groupCopy.spawnRepeat=30;
        var effect=new Track{id="tiled-effect",name="tiled-effect",kind="effect",effect="rgb",start=0,end=20,lane=5};for(int f=0;f<=20;f++)Motion.SetKey(effect,"fxOpacity",f,(1-Math.Cos(f*Math.PI/10))/2);TimelineEditing.Resize(effect,0,20,0,105,"sync");s.tracks.Add(effect);Motion.Normalize(s);string before=Json.Write(Sample(s,35));TimelineEditing.Organize(s);Check(Json.Write(Sample(s,35))==before,"Organizing changed copied group/random instances");return s;
    }
    static void Geometry(){var a=new BulletAction{generationPreset=CopyGeneration.Key,copyCount=2,copySpacingX=40};Check(CopyGeneration.Placements(a).Count==8,"Direction layers");a.copyMode="grid";a.copyWidth=200;a.copyHeight=100;a.copySpacingX=100;a.copySpacingY=100;a.copyAngle=90;var grid=CopyGeneration.Placements(a);Check(grid.Count==6,"Grid dimensions must be pixels, not cell counts");Near(grid[0].x,-50,"Grid rotated x");Near(grid[0].y,100,"Grid rotated y");a.copyWidth=a.copyHeight=200;a.copyCenter=false;Check(CopyGeneration.Placements(a).Count==8,"Grid excluded center");a.copyCenter=true;Check(CopyGeneration.Placements(a).Count==9,"Grid included center");a.copyMode="circle";a.copyRadius=100;a.copyCount=4;a.copyAngle=0;var p=CopyGeneration.Placements(a);Near(p[1].x,0,"Circle x");Near(p[1].y,-100,"Circle y");a.copyFacing="inward";Near(CopyGeneration.Rotation(a,p[0],40,30),150,"Inward copy must subtract template's starting orientation");a.copyColorMode="rainbow";Check(CopyGeneration.Tint(a,p[0]).Value.R==255&&CopyGeneration.Tint(a,p[2]).Value.G==255,"Per-copy rainbow colors");}
    static void Stretch(){var t=new Track{id="scale",kind="object",start=10,end=110};Motion.SetKey(t,"x",10,0);Motion.SetKey(t,"x",60,50);Motion.SetKey(t,"x",110,100);var keep=t.Snapshot();TimelineEditing.Resize(keep,10,110,10,210,"keep");Check(keep.keyframes[1].frame==60,"Keep mode moved keys");TimelineEditing.Resize(t,10,110,20,220,"scale");Check(t.keyframes.Select(k=>k.frame).SequenceEqual(new[]{20,120,220}),"Proportional scaling");
        var fx=new Track{id="dense",kind="effect",start=0,end=20};for(int i=0;i<=20;i++)Motion.SetKey(fx,"fxOpacity",i,(1-Math.Cos(i*Math.PI/10))/2);TimelineEditing.Resize(fx,0,20,0,65,"sync");Check(fx.keyframeCycle.length==21&&fx.keyframes.Count==66,"Dense preset not filled frame by frame");Near(Motion.Value(fx,"fxOpacity",26),Motion.Value(fx,"fxOpacity",5),"Repeated cycle shape");var saved=fx.Snapshot();TimelineEditing.Resize(fx,0,65,0,7,"sync");TimelineEditing.Resize(fx,0,7,0,85,"sync");Check(fx.keyframeCycle.length==21,"Shrinking lost the original cycle");Near(Motion.Value(fx,"fxOpacity",68),Motion.Value(saved,"fxOpacity",5),"Regrowth changed original style");var preset=TrackPreset.Capture("cycle",new[]{fx},50).Instantiate(100,100).Single();Check(preset.keyframeCycle.length==42,"FPS cycle length");TimelineEditing.Resize(preset,100,270,100,400,"sync");Check(preset.keyframeCycle.length==42,"Copied cycle was treated as one expanded pattern");var clone=fx.Snapshot();clone.keyframeCycle.keys[0].value=77;Check(fx.keyframeCycle.keys[0].value!=77,"Snapshot shared cycle samples");
        Motion.SetKey(fx,"fxOpacity",5,.123);TimelineEditing.Resize(fx,0,85,0,100,"sync");Near(Motion.Value(fx,"fxOpacity",5),.123,"Editing a repeated key was discarded");
        var moving=new Track{id="path-and-angle",kind="camera",start=0,end=50};MotionPresets.Apply(moving,"水平滑入",0);Motion.SetKey(moving,"angle",0,0);Motion.SetKey(moving,"angle",50,90);TimelineEditing.Resize(moving,0,50,0,100,"sync");Check(moving.keyframes.Count(k=>k.property=="x")==101,"Bound motion not rebaked");Check(moving.keyframes.Single(k=>k.property=="angle"&&k.value==90).frame==100,"Bound motion skipped other attributes");Check(moving.keyframeCycle==null,"Automatic XY made a sparse camera repeat");Check(new WorkspaceView().stretchKeys=="sync","Fresh workspace should synchronize resized keys");
        for(int f=0;f<=100;f++)Motion.SetKey(moving,"angle",f,Math.Sin(f*Math.PI/50));TimelineEditing.Resize(moving,0,100,0,200,"sync");var movedPreset=TrackPreset.Capture("path-cycle",new[]{moving},50).Instantiate(0,100).Single();TimelineEditing.Resize(movedPreset,0,400,0,600,"sync");Check(movedPreset.keyframeCycle.length==202,"Motion path keys invalidated non-position cycle after FPS conversion");
        var flight=new Track{id="speed-cycle",kind="emitter",start=0,end=10};Motion.SetKey(flight,"speed",0,10);Motion.SetKey(flight,"speed",10,20);TimelineEditing.Resize(flight,0,10,0,30,"repeat");var slower=TrackPreset.Capture("speed-cycle",new[]{flight},50).Instantiate(0,100).Single();TimelineEditing.Resize(slower,0,60,0,100,"repeat");Near(Motion.Value(slower,"speed",10),7.5,"FPS conversion did not scale saved cycle values");
    }
    static void Organize(){var a=Rod("rod");a.lane=0;var variable=new Track{id="var",kind="variable",start=0,end=0,lane=4,variableName="q",variableExpression="3"};var emitter=new Track{id="emitter",kind="emitter",start=0,end=80,count=1,interval=10,speed=2,lane=1};var camera=new Track{id="camera",kind="camera",start=0,end=80,lane=9};var s=Scene(a,emitter,variable,camera);string[] order=s.tracks.Select(t=>t.id).ToArray();string before=Json.Write(Sample(s,30));TimelineEditing.Organize(s);Motion.Normalize(s);Check(s.tracks.Select(t=>t.id).SequenceEqual(order),"Visual organizing changed execution order");Check(variable.lane<camera.lane&&camera.lane<emitter.lane&&emitter.lane<a.lane,"Kind sorting");Check(Json.Write(Sample(s,30))==before,"Organizing changed motion/random state");}
    static void UI(string root){using(var form=new MainForm(root)){var a=new Track{id="a",name="A",kind="object",start=0,end=49,lane=0};var b=new Track{id="b",name="B",kind="object",start=50,end=99,lane=0};var s=Scene(a,b);Set(form,"state",s);Set(form,"document",new LoadData{state=s,room=new RoomData(),project=root,projectName="copy editing",inventory=new Inventory{objects=new string[0],sprites=new[]{"sprCherry"},scripts=new string[0]},waveform=new WaveData()});var timeline=(TimelineCanvas)Get(form,"timeline");timeline.State=s;Call(form,"SelectTrack",a,null);timeline.Parent.Controls.Remove(timeline);using(var host=new Panel{Size=new Size(1300,300),BackColor=Theme.Panel}){timeline.Dock=DockStyle.Fill;host.Controls.Add(timeline);host.CreateControl();timeline.PixelsPerSecond=500;timeline.RefreshLayout();var left=timeline.ClipBounds(a);var right=timeline.ClipBounds(b);Near(left.Right,right.Left,"Touching clips still have a one-frame gap");using(var image=new Bitmap(host.Width,host.Height)){host.DrawToBitmap(image,host.ClientRectangle);image.Save(Path.Combine(root,"adjacent-seam.png"));var color=image.GetPixel((int)right.Left,(int)right.Top+12);Check(color.R>240&&color.G>240&&color.B>240,"Touching seam is not white");}host.Controls.Remove(timeline);}
            Motion.SetKey(a,"x",0,100);Motion.SetKey(a,"x",49,400);Call(form,"SelectTrack",a,null);Set(form,"stretchKeys","scale");((SelectionTimeControl)Get(form,"rightTime")).EditRange(0,98);Check(a.keyframes.Last().frame==98,"Inspector range bypassed stretch mode");Call(form,"Undo",false);Check(((EditorState)Get(form,"state")).tracks.Single(t=>t.id=="a").end==49,"Stretch undo");Call(form,"OrganizeTimeline");Check(((EditorState)Get(form,"state")).preserveTrackOrder,"Organizer button not wired");Call(form,"Undo",false);Check(!((EditorState)Get(form,"state")).preserveTrackOrder,"Organizer undo");var source=((EditorState)Get(form,"state")).tracks[0];Call(form,"ApplyGenerationPreset",CopyGeneration.Key,source);Check(source.spawnActions.Last().generationPreset==CopyGeneration.Key,"Copy preset not attached");var props=(ParameterInspector)Get(form,"behaviorProperties");Check(TypeDescriptor.GetProperties(props.SelectedObject)["复制排列"]!=null,"Copy controls absent from inspector");TypeDescriptor.GetProperties(props.SelectedObject)["复制排列"].SetValue(props.SelectedObject,"网格铺满复制");Check(TypeDescriptor.GetProperties(props.SelectedObject)["网格间距 X"]!=null,"Changing mode did not expose grid controls");TypeDescriptor.GetProperties(props.SelectedObject)["副本配色"].SetValue(props.SelectedObject,"按副本顺序彩虹");InspectorImage(props,Path.Combine(root,"copy-grid-zh.png"));Language.Select(root,"en");form.RefreshLanguageUI();InspectorImage(props,Path.Combine(root,"copy-grid-en.png"));Language.Select(root,"zh-CN");form.RefreshLanguageUI();Call(form,"SaveWorkspaceView");Check(WorkspaceView.Load(root).stretchKeys=="scale","Stretch preference not saved");
        }}
    [STAThread]static int Main(string[] args){try{if(args[0]=="--samples"){var s=Json.Read<EditorState>(File.ReadAllText(args[1]));Motion.Normalize(s);var output=new Dictionary<string,object>();foreach(int f in args[2].Split(',').Select(Int32.Parse))output[f.ToString()]=Sample(s,f);File.WriteAllText(args[3],Json.Write(output));return 0;}Application.EnableVisualStyles();Geometry();Stretch();Organize();UI(args[0]);var state=Fixture();File.WriteAllText(Path.Combine(args[0],"scene.json"),Json.Write(state));var w=new BulletWorld(state);w.Seek(65);string expected=Json.Write(Rows(w));w.Seek(1);w.Seek(65);Check(Json.Write(Rows(w))==expected,"Copy rewind changed state");Console.WriteLine("PASS: copy geometry/facing/palette, whole-object/group templates, dense repeat/shrink/regrow/FPS/snapshot, organizing without execution changes, inclusive clip seams, inspector resize and undo.");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
